//! `llvm` generated by `mlirformat tblgen` (`llvm.gen.rs`) against the `mlir-opt` 22.1.8 fixtures.
//! One test crate per dialect so cargo builds them in parallel; `cargo test --features gen-tests`.

#[path = "../common/mod.rs"]
mod common;
#[path = "llvm.gen.rs"]
mod llvm;

#[test]
fn llvm_matches_mlir_opt() {
    let mut opt = mlirformat::MlirOpt::new();
    opt.register::<llvm::Llvm>();
    common::Fixtures::check_dialect(&opt, "llvm");
}
